CREATE FUNCTION merkat_test_assert(value boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION 'Verification failed: %',label; END IF; END $$;
SELECT merkat_test_assert((SELECT count(*)=8 FROM pg_class WHERE relname IN('ProfileAvatar','UserSettings','TabSession','PlanReminder','Notification','RecoveryCode','PushSubscription','PushDelivery') AND relrowsecurity),'new tables enable RLS');
SELECT merkat_test_assert(NOT has_table_privilege('anon','"RecoveryCode"','SELECT,INSERT,UPDATE,DELETE,TRUNCATE'),'anon has no recovery privileges');
SELECT merkat_test_assert(NOT has_table_privilege('authenticated','"ProfileAvatar"','SELECT,INSERT,UPDATE,DELETE,TRUNCATE'),'browser has no avatar table privileges');
INSERT INTO "User"(id,"onboardingCompletedAt") VALUES('00000000-0000-4000-8000-000000000001',now()),('00000000-0000-4000-8000-000000000002',now()),('00000000-0000-4000-8000-000000000003',now());
INSERT INTO "Profile"("userId",username,"displayName","updatedAt") VALUES('00000000-0000-4000-8000-000000000001','qa_alice','Alice',now()),('00000000-0000-4000-8000-000000000002','qa_bob','Bob',now()),('00000000-0000-4000-8000-000000000003','qa_casey','Casey',now());
INSERT INTO "ProfileAvatar"("userId",bytes,version,"updatedAt") VALUES('00000000-0000-4000-8000-000000000001',decode('ffd8ff','hex'),repeat('a',64),now());
DO $$ DECLARE rejected boolean:=false;BEGIN BEGIN UPDATE "ProfileAvatar" SET bytes=decode(repeat('aa',524289),'hex');EXCEPTION WHEN check_violation THEN rejected:=true;END;PERFORM merkat_test_assert(rejected,'oversized normalized avatar rejected');END $$;
DO $$ DECLARE rejected boolean:=false;BEGIN BEGIN INSERT INTO "UserSettings"("userId",theme)VALUES('00000000-0000-4000-8000-000000000001','PURPLE');EXCEPTION WHEN check_violation THEN rejected:=true;END;PERFORM merkat_test_assert(rejected,'invalid theme rejected');END $$;
