INSERT INTO "DirectParticipant"("conversationId","userId") VALUES('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001'),('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002'),('10000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000001'),('10000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000003') ON CONFLICT DO NOTHING;
