INSERT INTO "PlanParticipant"("planId","userId",response,subscribed) VALUES('20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','GOING',true);
INSERT INTO "PlanReminder"("planId","userId",version,"hoursBefore","dueAt") VALUES('20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001',1,24,now()+interval '1 day');
DO $$ DECLARE rejected boolean:=false;BEGIN BEGIN INSERT INTO "PlanReminder"("planId","userId",version,"hoursBefore","dueAt") VALUES('20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001',1,24,now()+interval '1 day');EXCEPTION WHEN unique_violation THEN rejected:=true;END;PERFORM merkat_test_assert(rejected,'duplicate logical reminder rejected');END $$;
INSERT INTO "TabSession"(id,"createdBy","clientId","directId",title,state) VALUES('30000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001',gen_random_uuid(),'10000000-0000-4000-8000-000000000001','Pub','{"participants":[],"orders":[],"payments":[],"settlements":[],"audit":[],"submissions":{},"snapshot":null}');
DO $$ DECLARE rejected boolean:=false;BEGIN BEGIN INSERT INTO "TabSession"("createdBy","clientId","directId",title,state) VALUES('00000000-0000-4000-8000-000000000001',gen_random_uuid(),'10000000-0000-4000-8000-000000000001','Duplicate','{}');EXCEPTION WHEN unique_violation THEN rejected:=true;END;PERFORM merkat_test_assert(rejected,'one active tab per conversation');END $$;
UPDATE "TabSession" SET "closedAt"=now(),state=jsonb_set(state,'{snapshot}','{"total":0}'),version=version+1 WHERE id='30000000-0000-4000-8000-000000000001';
DO $$ DECLARE rejected boolean:=false;BEGIN BEGIN UPDATE "TabSession" SET state=jsonb_set(state,'{orders}','[{"total":100}]'),version=version+1 WHERE id='30000000-0000-4000-8000-000000000001';EXCEPTION WHEN raise_exception THEN rejected:=true;END;PERFORM merkat_test_assert(rejected,'closed orders immutable');END $$;
DO $$ DECLARE rejected boolean:=false;BEGIN BEGIN UPDATE "TabSession" SET state=jsonb_set(state,'{snapshot}','{"total":999}'),version=version+1 WHERE id='30000000-0000-4000-8000-000000000001';EXCEPTION WHEN raise_exception THEN rejected:=true;END;PERFORM merkat_test_assert(rejected,'closed snapshot immutable');END $$;
DO $$ DECLARE rejected boolean:=false;BEGIN BEGIN INSERT INTO "TabSession"("createdBy","clientId","directId",title,state) VALUES('00000000-0000-4000-8000-000000000001',gen_random_uuid(),gen_random_uuid(),'Dangling','{}');EXCEPTION WHEN foreign_key_violation THEN rejected:=true;END;PERFORM merkat_test_assert(rejected,'tab scope foreign key');END $$;
UPDATE "DirectConversation" SET "lastSequence"=1 WHERE id='10000000-0000-4000-8000-000000000002';
DO $$ DECLARE rejected boolean:=false;BEGIN BEGIN INSERT INTO "DirectMessage"("conversationId","senderId","clientId",sequence,text,"planId") VALUES('10000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000001',gen_random_uuid(),1,'Wrong room','20000000-0000-4000-8000-000000000001');EXCEPTION WHEN raise_exception THEN rejected:=true;END;PERFORM merkat_test_assert(rejected,'cross-conversation structured card rejected');END $$;
INSERT INTO "Session"(id,"userId","tokenHash","expiresAt")VALUES('40000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001',repeat('b',64),now()+interval '30 days');
DO $$ DECLARE rejected boolean:=false;BEGIN BEGIN INSERT INTO "PushSubscription"("userId","sessionId",endpoint,p256dh,auth)VALUES('00000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000001','https://fcm.googleapis.com/test','public','auth');EXCEPTION WHEN raise_exception THEN rejected:=true;END;PERFORM merkat_test_assert(rejected,'push session/user binding');END $$;
INSERT INTO "RecoveryCode"("codeHash","userId")VALUES(repeat('c',64),'00000000-0000-4000-8000-000000000001');
WITH used AS (UPDATE "RecoveryCode" SET "usedAt"=now() WHERE "codeHash"=repeat('c',64) AND "usedAt" IS NULL RETURNING *) SELECT merkat_test_assert((SELECT count(*)=1 FROM used),'first recovery consumption');
WITH used AS (UPDATE "RecoveryCode" SET "usedAt"=now() WHERE "codeHash"=repeat('c',64) AND "usedAt" IS NULL RETURNING *) SELECT merkat_test_assert((SELECT count(*)=0 FROM used),'second recovery consumption rejected');
